#define main inventory_load_audit_unused
#include "item_inventory_v1.cpp"
#undef main
int main(int argc,char** argv){try{check(argc==3,"potion audit args");auto gold=file(argv[1]);R r{gold};check(r.bytes(4)==B({'P','O','T','1'}),"potion magic");std::string path=argv[2],e;auto data=file(path+"/loot_table_pyarray.bin"),names=file(path+"/loot_table_pyarraynames.bin"),schema=file(path+"/loot_table_pystructnames.bin");ItemTable table;check(load_items({data.data(),data.size()},{names.data(),names.size()},{schema.data(),schema.size()},table,e),"real table");auto count=r.word();unsigned comparisons=0,calls=0;
 for(unsigned k=0;k<count;++k){ItemInventoryV1 owner(table);owner.set_character(0x100000077);owner.project_potion_capacity(static_cast<std::int8_t>(r.word()));auto n=r.word();while(n--){auto type=r.word();auto value=r.word();auto expected=r.bytes(r.word());auto trace=r.bytes(std::size_t(r.word())*28);Context c;InventoryServicesV1 services{&c,service};check(type?owner.remove_one_potion(services,e):owner.set_potion_quantity(static_cast<std::int32_t>(value),services,e),"potion operation failure");check(snapshot(owner)==expected,"potion ownership differs");check(c.trace==trace,"potion source call order differs");if(owner.potion())check(owner.num_potions()==owner.potion()->signed_quantity(),"signed getter differs");++comparisons;calls+=c.calls;}}
 check(r.p==gold.size(),"potion gold suffix");ItemInventoryV1 owner(table);owner.set_character(1);Context c;InventoryServicesV1 s{&c,service};check(!owner.set_potion_quantity(-1,s,e)&&owner.items().empty()&&c.calls==0,"negative Debug boundary accepted");check(owner.set_potion_quantity(3,s,e),"construct");auto p=owner.potion();check(owner.set_potion_quantity(65536,s,e)&&owner.potion()==p&&owner.num_potions()==0,"nonzero input/zero stored incorrectly erased");check(owner.remove_one_potion(s,e)&&!owner.potion()&&owner.items().empty(),"zero stored removal");
 std::cout<<"{\"validation\":\"PASS\",\"comparisons\":"<<comparisons<<",\"ordered_required_services\":"<<calls<<",\"guards\":3,\"mismatches\":0}\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
